$path=Join-Path (Split-Path -Parent (Split-Path -Parent $PSScriptRoot)) 'CloseToHSL\\Core\Runtime\Memory\Translation\CpuSecondStageTranslationMechanism.cpp'
$text=[IO.File]::ReadAllText($path)
$encode=[regex]::Match($text,'(?s)unsigned long long CpuSecondStageNeutralAuxiliary::Encode\(.*?\)\s*\{[^{}]*\}').Value
$decode=[regex]::Match($text,'(?s)bool CpuSecondStageNeutralAuxiliary::TryDecode\(.*?\)\s*\{[^{}]*\}').Value
if(-not $encode -or -not $decode){throw 'Could not extract methods'}
$pre='enum class CpuSecondStageFaultKind : unsigned char { None=0, NotPresent=1, PermissionDenied=2, Misconfiguration=3, OutsideOwnedAddressSpace=4, SourceStale=5 }; enum class CpuInstructionTranslationAccessKind : unsigned char { None=0, InstructionFetch=1, ScalarLoad=2, ScalarStore=3 }; class CpuSecondStageNeutralAuxiliary { public: static unsigned long long Encode(CpuInstructionTranslationAccessKind, unsigned short, CpuSecondStageFaultKind, unsigned char); static bool TryDecode(unsigned long long, CpuSecondStageFaultKind&, CpuInstructionTranslationAccessKind&, unsigned short&, unsigned char&); };'
$test='int main(){ using F=CpuSecondStageFaultKind; using A=CpuInstructionTranslationAccessKind; F f; A a; unsigned short n; unsigned char l; for(int k=0;k<8;k++) for(int ac=0;ac<5;ac++) for(int size=0;size<3;size++) for(int lv=0;lv<4;lv++){ auto v=CpuSecondStageNeutralAuxiliary::Encode(static_cast<A>(ac),size,static_cast<F>(k),lv); bool ok=CpuSecondStageNeutralAuxiliary::TryDecode(v,f,a,n,l); bool expected=(k>=1 && k<=5 && ac>=1 && ac<=3 && size!=0 && (lv==1 || lv==2)); if(ok!=expected || static_cast<int>(f)!=k || static_cast<int>(a)!=ac || n!=size || l!=lv) return 1; if(CpuSecondStageNeutralAuxiliary::TryDecode(v|1,f,a,n,l)) return 2; } return 0; }'
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'second-stage-check.cpp'),$pre+"`r`n"+$encode+"`r`n"+$decode+"`r`n"+$test,[Text.Encoding]::ASCII)